<?php

declare(strict_types=1);
require_once __DIR__ . '/operations.php';
require_role('owner_admin');
header('Content-Type: application/json; charset=utf-8');

try {
    $employeeId=max(0,(int)($_GET['id']??0)); $section=(string)($_GET['section']??'overview');
    $employee=ops_rows('SELECT e.id,e.full_name,e.hire_date,e.working_days,e.shift_start,e.shift_end,e.late_grace_minutes,r.name role_name,r.role_key FROM ops_employees e JOIN ops_roles r ON r.id=e.role_id WHERE e.id=? AND e.status=\'active\' AND r.role_key<>\'owner_admin\' LIMIT 1',[$employeeId])[0]??null;
    if(!$employee){http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Employee not found.']);exit;}
    $zone=new DateTimeZone('Africa/Windhoek');$today=new DateTimeImmutable('today',$zone);$period=(string)($_GET['period']??'today');
    switch($period){case'yesterday':$from=$today->modify('-1 day');$to=$from;break;case'this_week':$from=$today->modify('monday this week');$to=$today;break;case'last_week':$from=$today->modify('monday last week');$to=$from->modify('+6 days');break;case'this_month':$from=$today->modify('first day of this month');$to=$today;break;case'last_month':$from=$today->modify('first day of last month');$to=$from->modify('last day of this month');break;case'custom':$from=new DateTimeImmutable((string)($_GET['date_from']??''),$zone);$to=new DateTimeImmutable((string)($_GET['date_to']??''),$zone);break;default:$period='today';$from=$today;$to=$today;}
    if($to<$from)throw new RuntimeException('The end date must be on or after the start date.');$settings=[];foreach(ops_rows('SELECT setting_key,setting_value FROM kpi_settings')as$row)$settings[(string)$row['setting_key']]=(string)$row['setting_value'];$dataStart=new DateTimeImmutable($settings['data_start_date']??'2026-07-01',$zone);$adoption=new DateTimeImmutable($settings['adoption_date']??'2026-07-14',$zone);$effective=$from<$dataStart?$dataStart:$from;$rateFrom=$effective<$adoption?$adoption:$effective;$fromSql=$effective->format('Y-m-d 00:00:00');$rateSql=$rateFrom->format('Y-m-d 00:00:00');$toSql=$to->format('Y-m-d 23:59:59');
    $payload=['ok'=>true,'employee'=>$employee,'section'=>$section,'period'=>['from'=>$from->format('Y-m-d'),'to'=>$to->format('Y-m-d'),'adoption_date'=>$adoption->format('Y-m-d'),'show_adoption_banner'=>$from<$adoption]];
    $sessions=ops_rows('SELECT DATE(DATE_ADD(login_at,INTERVAL 2 HOUR)) day,MIN(DATE_ADD(login_at,INTERVAL 2 HOUR)) first_login,MAX(DATE_ADD(COALESCE(logout_at,last_seen_at),INTERVAL 2 HOUR)) last_activity,SUM(TIMESTAMPDIFF(MINUTE,login_at,COALESCE(logout_at,last_seen_at)))/60 hours,COUNT(*) sessions FROM kpi_sessions WHERE user_id=? AND login_at BETWEEN ? AND ? GROUP BY DATE(DATE_ADD(login_at,INTERVAL 2 HOUR)) ORDER BY day',[$employeeId,$rateSql,$toSql]);
    if($section==='attendance'){$payload['rows']=$sessions;$payload['summary']=['days'=>count($sessions),'hours'=>array_sum(array_map(static fn($r)=>(float)$r['hours'],$sessions))];}
    elseif($section==='packing'){$payload['rows']=ops_rows("SELECT id,item_name,weight_class,quantity_planned,date_loaded,date_started,date_completed,packing_status,priority,TIMESTAMPDIFF(MINUTE,date_started,date_completed) active_minutes,frontdesk_website_updated,frontdesk_website_updated_at FROM ops_packing_tasks WHERE assigned_employee_id=? AND date_loaded BETWEEN ? AND ? AND deleted_at IS NULL ORDER BY date_loaded DESC LIMIT 300",[$employeeId,$fromSql,$toSql]);}
    elseif($section==='orders'){$payload['rows']=ops_rows("SELECT o.id,o.order_number,o.customer_name,o.status,o.total_amount,se.changed_at completed_at FROM kpi_status_events se JOIN ops_orders o ON o.id=se.record_id WHERE se.module='order' AND se.changed_by=? AND se.changed_at BETWEEN ? AND ? ORDER BY se.changed_at DESC LIMIT 300",[$employeeId,$fromSql,$toSql]);}
    elseif($section==='tasks'){$payload['rows']=ops_rows('SELECT id,task_name,status,priority,created_at,deadline,completed_at FROM ops_checklist_tasks WHERE assigned_employee_id=? AND created_at BETWEEN ? AND ? AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 300',[$employeeId,$fromSql,$toSql]);}
    elseif($section==='waybills'){$payload['rows']=ops_rows('SELECT id,waybill_reference,customer_name,uploaded_at,due_by,sent_at,status,TIMESTAMPDIFF(MINUTE,uploaded_at,sent_at) duration_minutes FROM hambelela_waybills WHERE (uploaded_by=? OR sent_by=?) AND uploaded_at BETWEEN ? AND ? AND deleted_at IS NULL ORDER BY uploaded_at DESC LIMIT 300',[$employeeId,$employeeId,$fromSql,$toSql]);}
    elseif($section==='quality'){$payload['rows']=ops_rows('SELECT id,error_title,category,severity,cause,status,logged_at,resolution FROM ops_error_logs WHERE employee_id=? AND logged_at BETWEEN ? AND ? AND deleted_at IS NULL ORDER BY logged_at DESC LIMIT 300',[$employeeId,$fromSql,$toSql]);}
    elseif($section==='bookkeeping'){$payload['rows']=ops_rows('SELECT id,recon_date,system_balance,counted_total,variance,variance_note,created_at FROM hambelela_cashbook_recon WHERE logged_by=? AND recon_date BETWEEN ? AND ? ORDER BY recon_date DESC',[$employeeId,$effective->format('Y-m-d'),$to->format('Y-m-d')]);}
    elseif($section==='trends'){$payload['sessions']=$sessions;$payload['packing']=ops_rows("SELECT DATE(date_completed) day,COUNT(*) items,SUM(CASE weight_class WHEN 'S' THEN ? WHEN 'M' THEN ? WHEN 'L' THEN ? WHEN 'XL' THEN ? ELSE ? END) points,AVG(TIMESTAMPDIFF(MINUTE,date_started,date_completed)) avg_minutes FROM ops_packing_tasks WHERE assigned_employee_id=? AND date_completed BETWEEN ? AND ? AND date_completed>=date_started AND deleted_at IS NULL GROUP BY DATE(date_completed) ORDER BY day",[(float)($settings['weight_points_s']??1),(float)($settings['weight_points_m']??3),(float)($settings['weight_points_l']??6),(float)($settings['weight_points_xl']??10),(float)($settings['weight_points_m']??3),$employeeId,$rateSql,$toSql]);}
    else{$pack=ops_rows("SELECT COUNT(*) items,COALESCE(SUM(CASE weight_class WHEN 'S' THEN ? WHEN 'M' THEN ? WHEN 'L' THEN ? WHEN 'XL' THEN ? ELSE ? END),0) points,AVG(CASE WHEN date_completed>=date_started THEN TIMESTAMPDIFF(MINUTE,date_started,date_completed) END) avg_minutes,SUM(packing_status NOT IN ('done','website','packed_label_needed','done_needs_label','label_created')) open_items FROM ops_packing_tasks WHERE assigned_employee_id=? AND date_loaded BETWEEN ? AND ? AND deleted_at IS NULL",[(float)($settings['weight_points_s']??1),(float)($settings['weight_points_m']??3),(float)($settings['weight_points_l']??6),(float)($settings['weight_points_xl']??10),(float)($settings['weight_points_m']??3),$employeeId,$fromSql,$toSql])[0]??[];$orders=ops_rows("SELECT COUNT(DISTINCT record_id) done FROM kpi_status_events WHERE module='order' AND changed_by=? AND new_status='completed' AND changed_at BETWEEN ? AND ?",[$employeeId,$fromSql,$toSql])[0]??[];$tasks=ops_rows("SELECT SUM(status IN ('completed','complete','approved')) done,SUM(status NOT IN ('completed','complete','approved')) pending FROM ops_checklist_tasks WHERE assigned_employee_id=? AND created_at BETWEEN ? AND ? AND deleted_at IS NULL",[$employeeId,$fromSql,$toSql])[0]??[];$errors=ops_rows("SELECT COUNT(*) total,SUM(cause='employee') employee_errors FROM ops_error_logs WHERE employee_id=? AND logged_at BETWEEN ? AND ? AND deleted_at IS NULL",[$employeeId,$fromSql,$toSql])[0]??[];$itemCount=(int)($pack['items']??0);$payload['summary']=['hours'=>array_sum(array_map(static fn($r)=>(float)$r['hours'],$sessions)),'days'=>count($sessions),'items'=>$itemCount,'points'=>(float)($pack['points']??0),'avg_minutes'=>$itemCount>=5&&$pack['avg_minutes']!==null?(float)$pack['avg_minutes']:null,'open_items'=>(int)($pack['open_items']??0),'orders'=>(int)($orders['done']??0),'tasks_done'=>(int)($tasks['done']??0),'tasks_pending'=>(int)($tasks['pending']??0),'errors'=>(int)($errors['employee_errors']??0)];}
    echo json_encode($payload,JSON_UNESCAPED_SLASHES);
}catch(Throwable$error){error_log(date(DATE_ATOM).' employee detail: '.$error->getMessage().PHP_EOL,3,BASE_PATH.'/logs/kpi_errors.log');http_response_code(500);echo json_encode(['ok'=>false,'message'=>'Employee performance is temporarily unavailable.']);}
